2	
3	import org.springframework.jdbc.core.JdbcTemplate;
4	import org.springframework.jdbc.core.RowMapper;
5	import org.springframework.stereotype.Repository;
6	
7	import java.sql.ResultSet;
8	import java.sql.SQLException;
9	import java.time.LocalDateTime;
10	import java.util.List;
11	import java.util.Optional;
12	
13	/**
14	 * 借出记录表访问。记录只追加；归还只允许一次条件更新（status 必须仍为 ACTIVE）。
15	 * 每件证物至多一笔 ACTIVE 借出，由证物行锁与服务层状态校验共同保证。
16	 */
17	@Repository
18	public class LoanRecordRepository {
19	
20	    private static final LoanRowMapper ROW_MAPPER = new LoanRowMapper();
21	
22	    private final JdbcTemplate jdbc;
23	
24	    public LoanRecordRepository(JdbcTemplate jdbc) {
25	        this.jdbc = jdbc;
26	    }
27	
28	    /**
29	     * 追加一笔 ACTIVE 借出记录；loan_key 全局唯一，冲突由唯一约束拒绝。
30	     */
31	    public void insert(String loanKey, String evidenceKey, String custodianId, String borrowerId,
32	                       String purpose, LocalDateTime loanAt, LocalDateTime dueAt,
33	                       LocalDateTime createdAt) {
34	        jdbc.update("""
35	                        INSERT INTO loan_record
36	                            (loan_key, evidence_key, custodian_id, borrower_id, purpose,
37	                             loan_at, due_at, status, seal_passed, return_note, returned_at, created_at)
38	                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, NULL, NULL, NULL, ?)
39	                        """,
40	                loanKey, evidenceKey, custodianId, borrowerId, purpose,
41	                loanAt, dueAt, LoanStatus.ACTIVE.name(), createdAt);
42	    }
43	
44	    /**
45	     * 按全局借出业务键查询。
46	     */
47	    public Optional<LoanRecord> findByLoanKey(String loanKey) {
48	        List<LoanRecord> rows = jdbc.query(
49	                "SELECT * FROM loan_record WHERE loan_key = ?", ROW_MAPPER, loanKey);
50	        return rows.stream().findFirst();
51	    }
52	
53	    /**
54	     * 查询证物当前未归还（ACTIVE）借出（调用前必须已锁定证物行）。
55	     */
56	    public Optional<LoanRecord> findActiveByEvidenceKey(String evidenceKey) {
57	        List<LoanRecord> rows = jdbc.query(
58	                "SELECT * FROM loan_record WHERE evidence_key = ? AND status = ?",
59	                ROW_MAPPER, evidenceKey, LoanStatus.ACTIVE.name());
60	        return rows.stream().findFirst();
61	    }
62	
63	    /**
