package com.example.starter.evidence.dto;

import java.util.List;

/**
 * 完整保管链视图：证物当前状态 + 全部交接记录 + 全部借出记录 + 全部封条核验记录（均按发生顺序）
 * + 涉及该证物的合并事件。别名的保管链在合并时冻结，后续主号交接不回写别名历史。
 *
 * @param evidence    证物当前视图（别名含指向最终主号的 aliasOf）
 * @param transfers   历史交接记录，只追加
 * @param loans       历史借出记录，只追加
 * @param inspections 历史封条核验记录（含归还时的封条核验），只追加
 * @param mergeEvents 涉及该证物的合并事件（作为主号或被合并号），只追加
 */
public record CustodyChainView(
        EvidenceView evidence,
        List<TransferView> transfers,
        List<LoanView> loans,
        List<InspectionView> inspections,
        List<MergeEventView> mergeEvents) {
}

package com.example.starter.evidence.dto;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 证物身份合并请求。仅两证物当前保管人可发起；主号保留，被合并号转为 ALIAS。
 * 两个证物须分别携带期望版本（旧版本 409）；两键必须不同。
 *
 * @param commandKey            幂等命令键（全局 requestId）
 * @param primaryKey            合并后保留的主号证物业务键
 * @param primaryExpectedVersion 主号期望版本
 * @param aliasKey              被合并转为别名的证物业务键
 * @param aliasExpectedVersion  别名期望版本
 */
public record MergeRequest(
        @NotBlank @Size(max = 64) String commandKey,
        @NotBlank @Size(max = 64) String primaryKey,
        @NotNull @Min(1) Long primaryExpectedVersion,
        @NotBlank @Size(max = 64) String aliasKey,
        @NotNull @Min(1) Long aliasExpectedVersion) {
}

package com.example.starter.evidence.dto;

import java.time.LocalDateTime;

/**
 * 合并事件视图：附在主号轨迹上，记录合并时两证物的身份与版本。
 *
 * @param primaryKey     合并后保留的主号证物业务键
 * @param aliasKey       被合并转为别名的证物业务键
 * @param actorId        执行合并的操作人（合并时两证物的当前保管人）
 * @param primaryVersion 合并完成时主号版本
 * @param aliasVersion   合并完成时别名版本
 * @param createdAt      合并时间（Asia/Shanghai）
 */
public record MergeEventView(
        String primaryKey,
        String aliasKey,
        String actorId,
        long primaryVersion,
        long aliasVersion,
        LocalDateTime createdAt) {
}

